export const SPORT_COLORS={taekwondo:['#00679d','#e8f6fc'],karate:['#6b4aa0','#f2edfb'],DEFAULT:['#4d6480','#edf2f7']};
export const SPORTS_MAX=5,NAME_MAX=50,CLUB_MAX=100,USERNAME_MIN=3,USERNAME_MAX=24,USERNAME_CHANGE_DAYS=30;
/** Names nobody may take (§7.2); every name starting with a RESERVED_PREFIXES entry is reserved too. */
export const RESERVED=['admin','administrator','root','matbravo','matdraw','meducase','moderator','mod','support','pomoc','kontakt','system','api','stripe','billing','null','undefined','organizator','sedzia','staff','team','official','info'];
export const RESERVED_PREFIXES=['matbravo','admin'];
const USERNAME_RE=/^[a-z][a-z0-9._]{2,23}$/;

/** PHP trim(): only " \t\n\r\0\x0B" at both ends (unlike String.prototype.trim). */
const phpTrim=s=>s.replace(/^[ \t\n\r\0\x0B]+|[ \t\n\r\0\x0B]+$/g,'');
/** Lower case and trimmed, ASCII letters only (as PHP strtolower); null for a non-string. */
export function normalizeUsername(value){return typeof value==='string'?phpTrim(value).replace(/[A-Z]/g,c=>c.toLowerCase()):null;}
/** 'valid' | 'invalid' | 'reserved' for a username after normalizeUsername (§7.2). */
export function validateUsername(value){
 const u=normalizeUsername(value);
 if(u===null||!USERNAME_RE.test(u)||/\.\.|\._|_\./.test(u)||u.endsWith('.'))return 'invalid';
 return RESERVED.includes(u)||RESERVED_PREFIXES.some(p=>u.startsWith(p))?'reserved':'valid';
}
/** First or last name (§7.1): NFC, trimmed, 1–max characters of letters, combining marks, space, - ' . with at least one letter; else null. */
export function validateName(value,max=NAME_MAX){
 if(typeof value!=='string'||ILL_FORMED.test(value))return null;
 const s=phpTrim(value.normalize('NFC'));const n=[...s].length;
 return n>=1&&n<=max&&/^[\p{L}\p{M} '.-]+$/u.test(s)&&/\p{L}/u.test(s)?s:null;
}
const TRANSLIT={'ł':'l','ś':'s','ż':'z','ź':'z','ą':'a','ę':'e','ć':'c','ń':'n','ó':'o'};
/** Lower-case ASCII form of a name for username suggestions: Polish letters transliterated, other marks dropped, only [a-z0-9] kept. */
export function slugName(value){
 if(typeof value!=='string'||ILL_FORMED.test(value))return '';
 return value.toLowerCase().replace(/[łśżźąęćńó]/g,c=>TRANSLIT[c]).normalize('NFD').replace(/\p{M}/gu,'').replace(/[^a-z0-9]/g,'');
}
/**
 * Username candidates from a first and last name (§7.2), best first: first.last, first_last, first.l2, requested+2,
 * firstlast, first.last2, first.l3, first_last2 (without a last name: first, requested+2, first2, first3). Too long parts
 * are cut so the number survives; only valid, non-reserved names other than the requested one, without duplicates.
 * The server returns at most 3 of them that are free.
 */
export function suggestUsernames(first,last,requested=''){
 const f=slugName(first),l=slugName(last),r=normalizeUsername(requested)??'';
 if(!/^[a-z]/.test(f))return [];
 const fit=(base,suffix='')=>base.slice(0,USERNAME_MAX-suffix.length).replace(/[._]+$/,'')+suffix;
 const req=validateUsername(r)==='valid'?fit(r,'2'):'';
 const list=l?[fit(f+'.'+l),fit(f+'_'+l),fit(f+'.'+l[0],'2'),req,fit(f+l),fit(f+'.'+l,'2'),fit(f+'.'+l[0],'3'),fit(f+'_'+l,'2')]:[fit(f),req,fit(f,'2'),fit(f,'3')];
 const out=[];for(const c of list)if(c&&c!==r&&!out.includes(c)&&validateUsername(c)==='valid')out.push(c);
 return out;
}

/** Lone surrogates: the JavaScript form of invalid UTF-8. */
const ILL_FORMED=/[\uD800-\uDBFF](?![\uDC00-\uDFFF])|(?<![\uD800-\uDBFF])[\uDC00-\uDFFF]/;
const textTrim=s=>s.replace(/^[\s\p{Z}]+|[\s\p{Z}]+$/gu,'');
/**
 * Mirror of Text::clean (backend/src/Text.php, §5.5), step by step: null for a non-string or ill-formed text; NFC; multiline:
 * CRLF/CR → LF; tab → space; \p{Cc} removed (except LF when multiline); \p{Cf} removed except U+200D; trimmed; multiline:
 * blank lines emptied, runs of more than 2 empty lines cut to 2, lines after the 19th joined into the 20th; trimmed again.
 */
export function cleanText(value,{multiline=false}={}){
 if(typeof value!=='string'||ILL_FORMED.test(value))return null;
 let s=value.normalize('NFC');
 if(multiline)s=s.replace(/\r\n|\r/g,'\n');
 s=s.replace(/\t/g,' ').replace(multiline?/(?!\n)\p{Cc}/gu:/\p{Cc}/gu,'');
 s=textTrim(s.replace(/(?!‍)\p{Cf}/gu,''));
 if(!multiline||!s.includes('\n'))return s;
 let lines=[],empty=0;
 for(const line of s.split('\n')){if(textTrim(line)===''){if(++empty>2)continue;lines.push('');}else{empty=0;lines.push(line);}}
 if(lines.length>20)lines=[...lines.slice(0,19),lines.slice(19).map(textTrim).filter(l=>l!=='').join(' ')];
 return textTrim(lines.join('\n'));
}
